#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CAPACITY 5

int main(int argc, char **argv) {
    long items[CAPACITY];
    int head = 0;      // index of front element
    int count = 0;     // number of elements in queue

    // If no arguments, print NOOP (original behavior when argc < 2)
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int i = 1; i < argc; ++i) {
        char *arg = argv[i];

        /* Simple commands without parameters */
        if (strcmp(arg, "NOOP") == 0) {
            puts("NOOP");
            continue;
        }
        if (strcmp(arg, "EMPTY") == 0) {
            puts("EMPTY");
            continue;
        }
        if (strcmp(arg, "FULL") == 0) {
            puts("FULL");
            continue;
        }
        if (strcmp(arg, "DEQ") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                long val = items[head];
                head = (head + 1) % CAPACITY;
                --count;
                printf("DEQ %ld\n", val);
            }
            continue;
        }
        if (strcmp(arg, "FRONT") == 0) {
            if (count == 0) {
                puts("EMPTY");
            } else {
                printf("FRONT %ld\n", items[head]);
            }
            continue;
        }

        /* ENQ command – can be "ENQ<number>" or just "E<number>" */
        if (arg[0] == 'E') {
            char *num_ptr = NULL;
            if (strncmp(arg, "ENQ", 3) == 0) {
                num_ptr = arg + 3; // skip "ENQ"
            } else {
                num_ptr = arg + 1; // skip the leading 'E'
            }
            char *endptr;
            long value = strtol(num_ptr, &endptr, 10);
            if (endptr == num_ptr) { // no digits parsed
                puts("ERR");
                continue;
            }
            if (count == CAPACITY) {
                puts("FULL");
                continue;
            }
            // enqueue
            items[(head + count) % CAPACITY] = value;
            ++count;
            printf("ENQ %ld\n", value);
            continue;
        }

        /* Anything else is an error */
        puts("ERR");
    }
    return 0;
}
